from paging import take_tail

def test_tail_all():
    assert take_tail([1, 2], 5) == [1, 2]

def test_tail_zero():
    assert take_tail([1, 2], 0) == []

def test_tail_exact():
    assert take_tail([1, 2, 3], 3) == [1, 2, 3]


from recursion import reverse_rec

def test_reverse_single():
    assert reverse_rec("z") == "z"

def test_reverse_empty():
    assert reverse_rec("") == ""

def test_reverse_long():
    assert reverse_rec("abcdef") == "fedcba"
